import csv
import io
import unittest
from collections import UserDict
from html.parser import HTMLParser

from solution import FormatError, encode_grid


class Collector(HTMLParser):
    def __init__(self):
        super().__init__()
        self.events = []

    def handle_starttag(self, tag, attrs):
        self.events.append(("start", tag))

    def handle_endtag(self, tag):
        self.events.append(("end", tag))

    def handle_data(self, data):
        if data.strip():
            self.events.append(("data", data))


class Row:
    def __init__(self, name, note):
        self.name = name
        self.note = note


class EncodeGridTests(unittest.TestCase):
    def test_aligned_mixed_records_none_and_widths(self):
        records = [UserDict({"name": "Al", "note": None}), Row("Beatrice", "ok")]
        self.assertEqual(
            encode_grid(records, ["name", "note"], "aligned"),
            "name     | note\n-------- | ----\nAl       |     \nBeatrice | ok  ",
        )

    def test_empty_records_still_have_aligned_headings(self):
        self.assertEqual(encode_grid([], ["x", "long"], "aligned"),
                         "x | long\n- | ----")

    def test_csv_quoting_order_and_lf_endings(self):
        output = encode_grid([
            {"a": "x,y", "b": 'say "hi"'},
            {"a": "line\nbreak", "b": None},
        ], (c for c in ["a", "b"]), "csv")
        self.assertEqual(output, 'a,b\n"x,y","say ""hi"""\n"line\nbreak",\n')
        self.assertEqual(list(csv.reader(io.StringIO(output))), [
            ["a", "b"], ["x,y", 'say "hi"'], ["line\nbreak", ""]
        ])
        self.assertNotIn("\r", output)

    def test_html_escapes_content_and_forms_one_table(self):
        output = encode_grid([{"<key>": "<&\"'"}], ["<key>"], "html")
        parser = Collector()
        parser.feed(output)
        self.assertEqual(sum(event == ("start", "table") for event in parser.events), 1)
        data = [value for kind, value in parser.events if kind == "data"]
        self.assertEqual(data, ["<key>", "<&\"'"])
        self.assertIn("&lt;key&gt;", output)
        self.assertIn("&lt;&amp;", output)
        self.assertNotIn("<key>", output)

    def test_missing_column_and_invalid_style(self):
        with self.assertRaises(KeyError) as caught:
            encode_grid([{"a": 1}], ["a", "missing"], "csv")
        self.assertEqual(caught.exception.args, ("missing",))
        for style in ("CSV", "", None, 1):
            with self.assertRaises(FormatError):
                encode_grid([], ["a"], style)
        self.assertTrue(issubclass(FormatError, ValueError))

    def test_column_validation_and_non_mutation(self):
        for columns in ([], [""], ["ok", 3]):
            with self.assertRaises((TypeError, ValueError)):
                encode_grid([], columns, "csv")
        record = {"a": [1, 2]}
        columns = ["a"]
        before = record["a"][:]
        encode_grid([record], columns, "csv")
        self.assertEqual(record["a"], before)
        self.assertEqual(columns, ["a"])


if __name__ == "__main__":
    unittest.main()

